CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS sites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS machines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid REFERENCES sites(id),machine_code text NOT NULL,name text,machine_type text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(site_id,machine_code));
CREATE TABLE IF NOT EXISTS breakdowns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),site_id uuid REFERENCES sites(id),machine_id uuid REFERENCES machines(id),reported_at timestamptz NOT NULL,completed_at timestamptz,status text NOT NULL DEFAULT 'OPEN',severity text NOT NULL DEFAULT 'MEDIUM',category text,reason text NOT NULL,description text,root_cause text,corrective_action text,downtime_minutes integer GENERATED ALWAYS AS (CASE WHEN completed_at IS NULL THEN NULL ELSE GREATEST(0,EXTRACT(EPOCH FROM (completed_at-reported_at))/60)::integer END) STORED,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor text,action text NOT NULL,entity_type text,entity_id uuid,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_breakdowns_reported ON breakdowns(reported_at); CREATE INDEX IF NOT EXISTS idx_breakdowns_machine ON breakdowns(machine_id); CREATE INDEX IF NOT EXISTS idx_breakdowns_status ON breakdowns(status);